function normalize(name) {
  return (name || '').toLowerCase().trim().replace(/\s+/g, ' ');
}

export function getTeamNickname(name) {
  return TEAM_NICKNAMES[normalize(name)] || null;
}

/** "Texas" → "Texas Longhorns" ; unknown team → "Texas". */
export function getTeamDisplayName(name) {
  const nk = getTeamNickname(name);
  return nk ? `${name} ${nk}` : name;
}
